param([switch]$Policy,[switch]$Automatic,[switch]$Performance,[switch]$DnsOutage,[switch]$DnsFallback,[switch]$Pages,[switch]$MediaPages,[switch]$Coverage,[switch]$Dpi,[switch]$LivePaths,[switch]$TcpSegments,[switch]$ExperimentalCore,[string]$AgentFolder='runtime/native-agent-backend-lab')
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'));$run=[guid]::NewGuid().ToString('N')
$agentRoot=[IO.Path]::GetFullPath((Join-Path $root $AgentFolder));if(-not $agentRoot.StartsWith((Join-Path $root 'runtime')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Unexpected controller test directory'}
. (Join-Path $root 'runtime/vm-lab/W11-Calls.ps1')
try {
 W11-Call @('start',$labVmx,'nogui')|Out-Null
 $core=if($Dpi -or $LivePaths -or $ExperimentalCore){'runtime/native-core-dpi-experimental.exe'}else{'runtime/native-core-lab.exe'}
 foreach($pair in @(@('runtime/native-guard-lab.exe','native-guard-lab.exe'),@($core,'native-core-lab.exe'),@('runtime/native-awg-lab.exe','native-awg-lab.exe'),@('tools/native-guard-lab/Run-GuestDirect.ps1','Run-GuestDirect.ps1'))){W11-Call @('copyFileFromHostToGuest',$labVmx,(Join-Path $root $pair[0]),('C:\CitaLab\NativeAwg\'+$pair[1]))|Out-Null}
 foreach($name in @('Cita.NativeAgentLab.exe','Cita.NativeAgentLab.dll','Cita.NativeAgentLab.deps.json','Cita.NativeAgentLab.runtimeconfig.json')){W11-Call @('copyFileFromHostToGuest',$labVmx,(Join-Path $agentRoot $name),('C:\CitaLab\NativeAwg\AgentBackend\'+$name))|Out-Null}
 $mode=if($LivePaths -and $TcpSegments){' -LivePaths -TcpSegments'}elseif($LivePaths){' -LivePaths'}elseif($Dpi -and $Automatic){' -Dpi -Automatic'}elseif($Dpi){' -Dpi'}elseif($DnsOutage){' -DnsOutage'}elseif($DnsFallback){' -DnsFallback'}elseif($MediaPages){' -MediaPages'}elseif($Pages){' -Pages'}elseif($Coverage){' -Coverage'}elseif($Performance){' -Performance'}elseif($Automatic){' -Automatic'}elseif($Policy){' -Policy'}else{''};W11-Code ('& C:\CitaLab\NativeAwg\Run-GuestDirect.ps1 -Run '+$run+$mode+';exit 0')|Out-Null
 $prefix=if($LivePaths){'native-live-paths-'}elseif($DnsOutage){'native-dns-outage-'}elseif($DnsFallback){'native-dns-fallback-'}elseif($MediaPages){'native-media-pages-'}elseif($Pages){'native-pages-'}elseif($Coverage){'native-coverage-'}elseif($Performance){'native-performance-'}elseif($Automatic){'native-policy-auto-'}elseif($Policy){'native-policy-session-'}else{'native-direct-'}
 $file=Join-Path $root ('runtime/'+$prefix+$run+'.json');W11-Call @('copyFileFromGuestToHost',$labVmx,'C:\CitaLab\NativeAwg\native-direct-result.json',$file)|Out-Null
 $result=Get-Content $file -Raw|ConvertFrom-Json;$matched=$result.ownerSha256 -eq (Get-FileHash (Join-Path $root 'runtime/native-awg-lab.exe')).Hash -and $result.guardSha256 -eq (Get-FileHash (Join-Path $root 'runtime/native-guard-lab.exe')).Hash -and $result.controllerSha256 -eq (Get-FileHash (Join-Path $agentRoot 'Cita.NativeAgentLab.dll')).Hash -and $result.coreSha256 -eq (Get-FileHash (Join-Path $root $core)).Hash
 $result|Add-Member -NotePropertyName hashesMatched -NotePropertyValue $matched;$result|ConvertTo-Json -Depth 12|Set-Content $file -Encoding UTF8
 if($MediaPages){$brief=@();foreach($page in $result.pages.results){$brief+=@{page=$page.page;elapsedMs=$page.elapsedMs;stage=$page.stage;auditFailure=$page.auditFailure;ready=$page.dom.ready;video=$page.dom.video;failureCount=@($page.failures).Count}};@{success=$result.success;allPagesAudited=$result.pages.allPagesAudited;youtubePlaybackAdvanced=$result.pages.youtubePlaybackAdvanced;independentCleanupConfirmed=$result.independentCleanupConfirmed;hashesMatched=$matched;resultFile=$file;pages=$brief;failedStage=$result.failedStage;errorType=$result.errorType;validation=$result.runtime.validation}|ConvertTo-Json -Depth 8 -Compress|Write-Output}else{$result|ConvertTo-Json -Depth 12 -Compress|Write-Output}
 if(-not $result.success -or -not $result.independentCleanupConfirmed -or -not $matched){throw 'Native Direct scope acceptance incomplete'}
}finally{$labCredential=$null;$labVmCredential=$null}
